/// The `fah` executable: a terminal coding agent on top of
/// `flutter_agent_harness`.
///
/// Usage:
///
/// ```sh
/// dart run bin/fah.dart [--model <id>] [--provider <kind>] [--base-url <url>]
///                       [--cwd <dir>] [--session-root <dir>]
/// dart run bin/fah.dart [options] "summarize the changelog"   # headless
/// dart run bin/fah.dart --prompt-file prompt.md               # from file
/// dart run bin/fah.dart [options] notes.md "summarize this"   # file prompt
/// ```
///
/// With no prompt arguments the CLI starts an interactive REPL; with `-p`/
/// `--prompt` or positional arguments it runs a single headless prompt and
/// exits (response on stdout, diagnostics on stderr). Run with `--help` for
/// the full reference (`cliHelpText` in `lib/src/cli/cli_help.dart`).
///
/// API keys come from the environment: `OPENROUTER_API_KEY` (fallback
/// `OPENAI_API_KEY`) for the default `openai-completions` provider,
/// `ANTHROPIC_API_KEY` for `anthropic`, `GOOGLE_API_KEY` for `google`.
///
/// This is one of the two places `dart:io` is allowed (the other is
/// `lib/io.dart`); everything it drives is pure Dart.
library;

import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';
import 'package:http/http.dart' as http; // the auto-update probe client
import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_agent_harness/io.dart';
import 'package:flutter_agent_harness/src/cli/ansi_markdown.dart';
import 'package:flutter_agent_harness/src/cli/boot_update.dart';
import 'package:flutter_agent_harness/src/cli/ext_cli.dart';
import 'package:flutter_agent_harness/src/cli/jsr_cli.dart';
import 'package:flutter_agent_harness/src/cli/session_tree.dart';
import 'package:flutter_agent_harness/src/cli/session_repair_command.dart';
import 'package:flutter_agent_harness/src/cli/tui_key_hints.dart';
import 'package:flutter_agent_harness/src/cli/trajectory_tui.dart';
import 'package:flutter_agent_harness/src/hub/hub_teardown_error.dart';
import 'package:flutter_agent_harness/src/prompts/prompts.g.dart';
import 'package:yaml/yaml.dart' as yaml;
// The ONLY place the core CLI imports the hub client package: downstream
// forks that want a different or no hub client patch this import and the
// 'hub' case in `_builtInPlugin`.
import 'package:fa_hub_client/fa_hub_client.dart'
    show
        HubConfig,
        HubPlugin,
        defaultDapConfigFile,
        envClientSecret,
        envMasterSecret,
        persistDapConfig,
        readDapConfig,
        resolveDapSettings;
import 'fah_dap_command.dart';
import 'fah_hub_plugin.dart';
import 'fah_hub_serve.dart';
import 'hub_fabric_repository.dart';
import 'package:flutter_agent_harness/src/hub/hub_boot_credential.dart';
import 'self_manage.dart';
import 'serve_a2a.dart';
import 'serve_bridge.dart';
import 'fah_boot_restore.dart';
import 'fah_wire_serve.dart';
import 'package:flutter_agent_harness/src/cli/provider_export.dart';

part 'fah_util.dart';
part 'fah_model.dart';
part 'fah_io.dart';
part 'fah_trajectory.dart';
part 'fah_runapp.dart';
part 'fah_wire_host.dart';

Future<void> main(List<String> args) async {
  // Provider forensics composition root (gh-1395 review round 1): the
  // pure barrel carries only the contracts; the io seams (env knob
  // lookup, [conn-trace] stderr lines, the observed dart:io client, the
  // sentinel's disk sink) install here — the ONE dart:io boundary.
  installProviderStallForensics();
  // Session segment rotation warnings (fa gh-1077): the session layer has
  // no console dependency — the CLI surfaces hard-cap truncations and
  // rotation fallbacks on stderr.
  JsonlSessionStorage.onRotationWarning = stderr.writeln;
  await runZoned(
    () => _runApp(args),
    zoneSpecification: ZoneSpecification(
      handleUncaughtError: (self, parent, zone, error, stackTrace) {
        // fa_hub_client can fail a LEAKED waiter (no listener left) with
        // StateError('connection closed') when the socket drops — e.g. a
        // flush() waiter abandoned after _send threw on a dead socket.
        // The error lands here as an unhandled async error no call-site
        // try/catch can reach; the fabric already fell back to files, so
        // log it and keep running instead of crashing the CLI.
        if (isHubConnectionTeardown(error)) {
          stderr.writeln(
            'fa: hub connection closed mid-operation — '
            'continuing on the file fabric',
          );
          return;
        }
        _handleUncaughtError(error, stackTrace);
      },
    ),
  );
}

String _resolveApiKey(
  String provider,
  SecureKeyCache keys, {
  String? fallback,
  String? baseUrl,
  Iterable<String>? scopedKeyNames,
}) {
  final key =
      optionalProviderApiKey(
        provider,
        keys,
        baseUrl: baseUrl,
        scopedKeyNames: scopedKeyNames,
      ) ??
      fallback;
  if (key == null || key.isEmpty) {
    _fail(
      'missing API key: set ${apiKeyEnvNames(provider).first} in the '
      'environment',
    );
  }
  return key;
}

String _defaultSessionRoot() {
  final home = _homeDir();
  if (Platform.isMacOS) {
    // Share sessions with the app only when macOS materialized its App
    // Group container (i.e. the entitled app is installed). Probing must
    // NOT create the container ourselves: under a fake HOME (integration
    // tests) that would silently relocate the sessions they then read.
    final container = '$home/Library/Group Containers/group.dev.fa1.shared';
    final groupDir = '$container/fa/sessions';
    if (Directory(container).existsSync() && _isDirWritable(groupDir)) {
      return groupDir;
    }
    return '$home/.fah/sessions';
  }
  return '$home/.fah/sessions';
}

bool _isDirWritable(String path) {
  try {
    final dir = Directory(path);
    if (!dir.existsSync()) {
      dir.createSync(recursive: true);
    }
    final probe = File('$path/.probe_${DateTime.now().microsecondsSinceEpoch}');
    probe.writeAsStringSync('');
    probe.deleteSync();
    return true;
  } catch (_) {
    return false;
  }
}

String _homeDir() {
  final home =
      Platform.environment['HOME'] ?? Platform.environment['USERPROFILE'];
  if (home == null || home.isEmpty) {
    _fail('cannot resolve home directory; pass --session-root');
  }
  return home;
}

/// This host's machine name for `name@machine` addressing (issue #27
/// phase 2). Null when the platform cannot name the host — suffixed
/// addresses then never resolve locally.
String? _localMachineName() {
  try {
    final name = Platform.localHostname.trim();
    return name.isEmpty ? null : name;
  } on Object {
    return null;
  }
}

/// The runtime `FA_PROVIDERS` env override, applied at startup (the
/// dart-define always wins over it; see [providerEnabledInBuild]).
void _applyProviderFilterEnv() {
  final value = Platform.environment['FA_PROVIDERS'];
  if (value != null && value.trim().isNotEmpty) {
    providerFilterEnvOverride = value;
  }
}

/// Truthy env-var check (`1`/`true`/`yes`/`on`, case-insensitive).
/// The inverse default for flags that are ON unless explicitly disabled:
/// unset or a truthy value → true; only `0`/`false`/`no`/`off` → false.
bool _envNotFalsy(String name) {
  final value = Platform.environment[name]?.trim().toLowerCase();
  return value != '0' && value != 'false' && value != 'no' && value != 'off';
}

/// Truthy env-var check for opt-in flags (`1`/`true`/`yes`/`on`).
bool _envTruthy(String name) {
  final value = Platform.environment[name]?.trim().toLowerCase();
  return value == '1' || value == 'true' || value == 'yes' || value == 'on';
}

/// Tri-state env-var check: `1/true/yes/on` → true, `0/false/no/off` →
/// false, unset or unrecognized (e.g. `auto`) → null. Strict sets — any
/// other garbage must not silently force the flag on.
bool? _envTristate(String name) {
  final raw = Platform.environment[name]?.trim().toLowerCase();
  if (raw == null || raw.isEmpty) return null;
  const on = {'1', 'true', 'yes', 'on'};
  const off = {'0', 'false', 'no', 'off'};
  if (on.contains(raw)) return true;
  if (off.contains(raw)) return false;
  return null;
}

/// The executable used to wake asleep cross-session mailboxes: this
/// process's own path when it is a compiled snapshot, or null to fall back
/// to `fa` on PATH (a `dart run` VM cannot be re-spawned with session
/// args).
String? wakeExecutable() {
  final exe = Platform.script.toFilePath();
  final base = exe.split(Platform.pathSeparator).last.toLowerCase();
  if (base == 'dart' || base == 'dart.exe') return null;
  return exe;
}

part of 'fah.dart';

const _fallbackVersion = '0.1.0';

/// Reads the package version with four fallbacks so compiled binaries stay
/// accurate: `-DFA_VERSION=` baked at compile time (legacy AOT builds), then
/// a `version.txt` file alongside the `dart build cli` bundle, then the
/// `pubspec.yaml` next to the executable (source runs), then the constant.
String _packageVersion() {
  const fromEnv = String.fromEnvironment('FA_VERSION');
  if (fromEnv.isNotEmpty) return fromEnv;
  try {
    // Platform.resolvedExecutable always returns the full canonical path,
    // even when the binary was invoked via a bare name or relative path.
    // Platform.script may return a relative path on some platforms, which
    // makes exeDir = cwd instead of the binary's real directory.
    final exePath = Platform.resolvedExecutable;
    final exeDir = File(exePath).parent;
    final bundleRoot = exeDir.parent;
    // Try bundle/version.txt first (dart build cli layout).
    final versionFile = File('${bundleRoot.path}/version.txt');
    if (versionFile.existsSync()) {
      final v = versionFile.readAsStringSync().trim();
      if (v.isNotEmpty) return v;
    }
    // Try <exe_dir>/version.txt (installer layout: version.txt next to fa).
    final dirVersionFile = File('${exeDir.path}/version.txt');
    if (dirVersionFile.existsSync()) {
      final v = dirVersionFile.readAsStringSync().trim();
      if (v.isNotEmpty) return v;
    }
    // Source run: pubspec.yaml sits two levels up from bin/.
    final pubspec = File('${bundleRoot.path}/pubspec.yaml');
    final doc = yaml.loadYaml(pubspec.readAsStringSync()) as Map;
    final value = doc['version'];
    if (value is String && value.isNotEmpty) return value;
  } on Object {
    // Fall back to the compile-time constant when nothing is available.
  }
  return _fallbackVersion;
}

Never _fail(String message) {
  stderr.writeln('fa: $message');
  stderr.writeln('Run with --help for usage.');
  exit(64);
}

Never _exitWithUsage(String version) {
  stdout.write(cliHelpText(version));
  exit(0);
}

/// Set once the first SIGTERM arrived in a headless run (issue #155): a
/// second one escalates from graceful to forced.
var _sigtermSeen = false;

/// The in-flight headless run, awaited by the SIGINT/SIGTERM graceful
/// exits (issue #155). Set before the signals can matter, read only from
/// the exit paths.
Future<int>? _headlessRun;

/// wire-serve (issue #1103): ends the transport (completing the serve
/// future) so a signal-driven exit tears down GRACEFULLY — runWireServe's
/// finally aborts any in-flight run, persists, and the process exits.
/// Null outside wire-serve mode.
void Function()? _wireServeSettle;

/// Graceful headless abort shared by SIGINT and SIGTERM (issue #155):
/// abort the run, wait for it to settle (bounded — a wedged provider
/// cannot hold the exit), flush the HEP stream, exit 130.
void _gracefulHeadlessExit(void Function() fireInterrupt) {
  fireInterrupt();
  _wireServeSettle?.call();
  final run = _headlessRun;
  unawaited(
    Future(() async {
      if (run != null) {
        await run.timeout(const Duration(seconds: 10), onTimeout: () => 130);
      }
      // gh-1455: drain the serialized line chain instead of a bare flush —
      // a flush racing the in-flight per-line flushes is the exact
      // "StreamSink is bound to a stream" teardown crash.
      await drainStdoutLines();
    }).whenComplete(() => exit(130)),
  );
}

/// gh-1455: the ONE write+flush chain for headless stdout (HEP v1 and
/// stream-json lines). `stdout.flush()` marks the sink "bound" while in
/// flight, so the old unawaited per-line `stdout.flush()` racing the next
/// `writeln` — or the exit paths' own flush — threw the synchronous
/// `StateError("StreamSink is bound to a stream")` from an event-callback
/// frame: an uncaught zone error that crashed shutdown (crash.log) and let
/// the process linger until the runner's stall-kill. Every link is
/// guarded, so the chain itself can never reject; nothing escapes after
/// teardown.
Future<void> _stdoutLineChain = Future<void>.value();

/// Appends one line to [_stdoutLineChain] — write, then flush, both
/// guarded. Never throws.
void _enqueueStdoutLine(String line) {
  _stdoutLineChain = _stdoutLineChain.then((_) async {
    try {
      stdout.writeln(line);
      await stdout.flush();
    } on Object {
      // The sink is being torn down (or its stream already closed): a
      // crashed writer must not surface as an uncaught zone error.
    }
  });
}

/// Drains the line chain and flushes once more — the exit paths call this
/// instead of a bare `await stdout.flush()` so a final flush can never
/// overlap an in-flight chain link. Re-drains while stragglers enqueue
/// behind us (bounded), so the final flush is the true last sink
/// operation. Never throws.
Future<void> drainStdoutLines() async {
  for (var round = 0; round < 8; round++) {
    final chain = _stdoutLineChain;
    await chain;
    if (identical(chain, _stdoutLineChain)) break;
  }
  try {
    await stdout.flush();
  } on Object {
    // Same teardown guard as [_enqueueStdoutLine].
  }
}

/// One HEP JSONL line to stdout, flushed immediately (issue #155): a
/// supervisor tailing the pipe must never wait on a buffer.
void _writeHepLine(String line) {
  _enqueueStdoutLine(line);
}

/// One stream-json NDJSON line to stdout, flushed immediately (issue
/// #695): same live-pipe contract as HEP — `| jq` consumers tail the
/// stream line by line, and jsonEncode output is always single-line.
void _writeStreamJsonLine(String line) {
  _enqueueStdoutLine(line);
}

/// The mime reported when the magic-byte sniff misses — callers treat it
/// as "not an image" (issue #196 `--attach` passthrough).
const _unknownAttachMime = 'application/octet-stream';

/// Image type by magic bytes (issue #155 `--attach`): the file extension
/// is untrusted; the first bytes are. png/jpeg/gif/webp covered, else
/// [_unknownAttachMime].
String _sniffMime(Uint8List bytes) {
  bool startsWith(List<int> magic) {
    if (bytes.length < magic.length) return false;
    for (var i = 0; i < magic.length; i++) {
      if (bytes[i] != magic[i]) return false;
    }
    return true;
  }

  const png = [137, 80, 78, 71, 13, 10, 26, 10];
  if (startsWith(png)) return 'image/png';
  if (startsWith([0xFF, 0xD8, 0xFF])) return 'image/jpeg';
  if (startsWith([0x47, 0x49, 0x46, 0x38])) return 'image/gif';
  if (startsWith([0x52, 0x49, 0x46, 0x46]) &&
      bytes.length > 12 &&
      bytes[8] == 0x57 &&
      bytes[9] == 0x45 &&
      bytes[10] == 0x42 &&
      bytes[11] == 0x50) {
    return 'image/webp';
  }
  return _unknownAttachMime;
}

Never _exitWithVersion(String version, {String? output}) {
  if (output == 'json') {
    // Machine-readable for supervisors (issue #155): version + HEP
    // protocol version, one JSON object.
    stdout.writeln(jsonEncode({'version': version, 'hep': hepVersion}));
    exit(0);
  }
  stdout.writeln('fa $version');
  exit(0);
}

/// Writes an uncaught error to `~/.fah/crash.log` and stderr, then exits
/// non-zero. This is the last-resort handler so users can report what
/// happened instead of the CLI silently disappearing.
void _handleUncaughtError(Object error, StackTrace stackTrace) {
  final message = 'fa crashed: $error';
  stderr.writeln(message);
  if (error is SessionException ||
      message.contains('Failed to create session directory')) {
    stderr.writeln(
      '\nTip: If this is a permission issue with session storage, you can fix it by running:\n'
      '  sudo chown -R \$(whoami) ~/Library/"Group Containers"/group.dev.fa1.shared\n'
      '  chmod -R u+rwx ~/Library/"Group Containers"/group.dev.fa1.shared\n'
      'Or start fa with a custom session storage path:\n'
      '  fa --session-root ~/.fah/sessions\n',
    );
  }
  try {
    final home =
        Platform.environment['HOME'] ?? Platform.environment['USERPROFILE'];
    if (home != null && home.isNotEmpty) {
      final dir = Directory('$home/.fah');
      dir.createSync(recursive: true);
      final log = File('${dir.path}/crash.log');
      final timestamp = DateTime.now().toUtc().toIso8601String();
      final version = _packageVersion();
      final buffer = StringBuffer()
        ..writeln('timestamp: $timestamp')
        ..writeln('version: $version')
        ..writeln('type: ${error.runtimeType}')
        ..writeln('error: $error')
        ..writeln('stack:')
        ..writeln(stackTrace);
      log.writeAsStringSync('$buffer\n', mode: FileMode.append);
      stderr.writeln('details appended to ${log.path}');
    }
  } on Object catch (e) {
    stderr.writeln('could not write crash log: $e');
  }
  stderr.writeln('Run with --help for usage.');
  exit(1);
}

part of 'fah.dart';

Future<void> _runApp(List<String> args) async {
  final packageVersion = _packageVersion();
  _applyProviderFilterEnv();
  // Platform-aware chord display (issue #809): Option/Cmd labels on macOS.
  tuiKeyHintDarwin = Platform.isMacOS;
  // `fa serve [--a2a|--bridge] [--port N] [--token T]` — the parser does
  // not know the serve forms, so they are intercepted before CliArgs
  // parsing: serve-specific flags are stripped from the parsed args and
  // kept for the late interception below (after model/key resolution).
  final serve = splitServeA2aArgs(args);
  // `fa wire-serve [--port N] [--stdio] [--token T]` (issue #1103) — the
  // headless AWP server. Intercepted like serve: the parser does not know
  // the form, and the words must never reach prompt parsing. Flag errors
  // (--stdio with --port, a bad --port) are LOUD startup failures (E2) —
  // never a silent fallback to another mode.
  final WireServeArgs wireServe;
  try {
    wireServe = splitWireServeArgs(args);
  } on FormatException catch (error) {
    _fail(
      'usage: fa wire-serve [--port N] [--stdio] [--token T]\n'
      '${error.message}',
    );
  }
  // `fa hub serve [--port N]` — a local DAP hub, no agent boot
  // (docs/dap.md §8.1). Intercepted on the raw args BEFORE the serve
  // marker check below (`hub serve` contains the word "serve" but is a
  // different command): the words must never reach prompt parsing.
  if (args.isNotEmpty && args.first == 'hub') {
    exit(await runHubCommand(args.sublist(1)));
  }
  // `fa dap start|stop|status [--port N]` — the one-step local DAP hub
  // (issue #304): probe/spawn/enroll/stop with no agent boot, same raw-
  // args interception as `fa hub serve`.
  if (args.isNotEmpty && args.first == 'dap') {
    exit(await runDapCommand(args.sublist(1)));
  }
  final serveMarkerCount =
      (serve.serveA2a ? 1 : 0) + (serve.serveBridge ? 1 : 0);
  if (serveMarkerCount != 1 && args.contains('serve')) {
    _fail(
      'usage: fa serve --a2a [--port N] [--token T] | '
      'fa serve --bridge [--port N] [--token T]',
    );
  }

  late final CliArgs parsed;
  try {
    parsed = switch (parseCliArgs(
      wireServe.wireServe ? wireServe.cliArgs : serve.cliArgs,
    )) {
      CliArgsHelp() => _exitWithUsage(packageVersion),
      CliArgsVersion(:final output) => _exitWithVersion(
        packageVersion,
        output: output,
      ),
      final CliArgs cliArgs => cliArgs,
    };
  } on CliArgsException catch (error) {
    _fail(error.message);
  }

  // Quick self-management commands, intercepted before prompt resolution:
  // `fa update` swaps in the latest release binary; `fa uninstall` removes
  // the binary + PATH entry (and ~/.fah on a second confirmation).
  if (parsed.positionals.length == 1 && parsed.prompt == null) {
    switch (parsed.positionals.single) {
      case 'update':
        exit(await runSelfUpdate(currentVersion: packageVersion));
      case 'uninstall':
        exit(await runSelfUninstall());
    }
  }
  // `fa trajectory <verb> [sessionId] [--json] [--at N]` — read-only
  // trajectory views over a stored session; intercepted before prompt
  // resolution so the verb words never become a prompt.
  final trajectory = parsed.trajectory;
  if (trajectory != null) {
    exit(await _runTrajectoryCommand(trajectory, parsed));
  }

  // `fa ext <verb> ...` — headless JS extension management, intercepted
  // like trajectory: no agent boot, the exit code propagates.
  final ext = parsed.ext;
  if (ext != null) {
